import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

layernorm_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void layer_norm_kernel(const float* __restrict__ x,
                                   const float* __restrict__ gamma,
                                   const float* __restrict__ beta,
                                   float* __restrict__ out,
                                   int N, int D, float eps) {
    int n = blockIdx.x;
    if (n >= N) return;
    const float* x_n = x + (size_t)n * D;
    float* out_n = out + (size_t)n * D;
    int D4 = D / 4;
    const float4* x4 = reinterpret_cast<const float4*>(x_n);
    double sum = 0.0;
    double sumsq = 0.0;
    for (int i = threadIdx.x; i < D4; i += blockDim.x) {
        float4 v = x4[i];
        sum += (double)v.x + (double)v.y + (double)v.z + (double)v.w;
        sumsq += (double)v.x * (double)v.x + (double)v.y * (double)v.y +
                 (double)v.z * (double)v.z + (double)v.w * (double)v.w;
    }
    for (int i = D4 * 4 + threadIdx.x; i < D; i += blockDim.x) {
        float v = x_n[i];
        sum += (double)v;
        sumsq += (double)v * (double)v;
    }
    extern __shared__ double sdata[];
    double* s_sum = sdata;
    double* s_sumsq = sdata + blockDim.x;
    s_sum[threadIdx.x] = sum;
    s_sumsq[threadIdx.x] = sumsq;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + stride];
            s_sumsq[threadIdx.x] += s_sumsq[threadIdx.x + stride];
        }
        __syncthreads();
    }
    __shared__ double mean;
    __shared__ float invstd;
    if (threadIdx.x == 0) {
        mean = s_sum[0] / D;
        double var = s_sumsq[0] / D - mean * mean;
        invstd = rsqrtf((float)var + eps);
    }
    __syncthreads();
    const float4* gamma4 = reinterpret_cast<const float4*>(gamma);
    const float4* beta4 = reinterpret_cast<const float4*>(beta);
    float4* out4 = reinterpret_cast<float4*>(out_n);
    double mean_l = mean;
    float invstd_l = invstd;
    for (int i = threadIdx.x; i < D4; i += blockDim.x) {
        float4 v = x4[i];
        float4 g = gamma4[i];
        float4 b = beta4[i];
        float4 o;
        o.x = (float)((double)v.x - mean_l) * invstd_l * g.x + b.x;
        o.y = (float)((double)v.y - mean_l) * invstd_l * g.y + b.y;
        o.z = (float)((double)v.z - mean_l) * invstd_l * g.z + b.z;
        o.w = (float)((double)v.w - mean_l) * invstd_l * g.w + b.w;
        out4[i] = o;
    }
    for (int i = D4 * 4 + threadIdx.x; i < D; i += blockDim.x) {
        float v = x_n[i];
        out_n[i] = (float)((double)v - mean_l) * invstd_l * gamma[i] + beta[i];
    }
}

torch::Tensor layer_norm_cuda(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps) {
    auto x_contig = x.contiguous();
    auto out = torch::empty_like(x_contig);

    int64_t D = gamma.numel();
    int64_t N = x_contig.numel() / D;

    int threads = 1024;
    int blocks = (int)N;
    size_t shared_mem = 2 * threads * sizeof(double);

    layer_norm_kernel<<<blocks, threads, shared_mem>>>(
        x_contig.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        (int)N, (int)D, (float)eps
    );

    return out;
}
"""

layernorm_cpp_source = r"""
torch::Tensor layer_norm_cuda(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps);
"""

layernorm_module = load_inline(
    name="layernorm_module",
    cpp_sources=layernorm_cpp_source,
    cuda_sources=layernorm_source,
    functions=["layer_norm_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Layer Normalization using a custom CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5
        self.layernorm_module = layernorm_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.layernorm_module.layer_norm_cuda(x, self.weight, self.bias, self.eps)


batch_size = 16
features = 64
dim1 = 256
dim2 = 256


def get_inputs():
    x = torch.randn(batch_size, features, dim1, dim2)
    mean = 1000
    std_dev = 0.1
    x = x * std_dev + mean
    return [x.cuda()]


def get_init_inputs():
    return [(features, dim1, dim2)]

